import React, { useEffect, useMemo, useState,CSSProperties  } from "react";
import { GameState, VoiceState, OverlayState, ModsType } from "./common/AmongUsState";
import makeStyles from "@material-ui/core/styles/makeStyles";
import "./App.css";
import Avatar from "./Avatar";
import { ISettings } from "./common/ISettings";
import ioV2 from "socket.io-client";
import { io as ioV4 } from "socket.io-client-v4";
import { getAvatarColors } from "./common/AvatarGenerator";

export interface playerContainerCss extends CSSProperties {
  '--size': string;
}

interface UseStylesProps {
  height: number;
  width: number;
  oldHud: boolean;
}

interface signalData {
  from?: string;
  data: VoiceState | { type: 'obs-cosmetic'; source: string; png: string };
}

type CompatibleSocket = {
  connected?: boolean;
  disconnect: () => void;
  emit: (event: string, ...args: any[]) => void;
  on: (event: string, callback: (...args: any[]) => void) => void;
};

const useStyles = makeStyles(() => ({
  meetingHud: {
    position: 'absolute',
    top: '50%',
    left: '50%',
    width: ({ width }: UseStylesProps) => width,
    height: ({ height }: UseStylesProps) => height,
    transform: 'translate(-50%, -50%)',
  },
  tabletContainer: {
    width: ({ oldHud }: UseStylesProps) => (oldHud ? '88.45%' : '100%'),
    height: '10.5%',
    left: ({ oldHud }: UseStylesProps) => (oldHud ? '4.7%' : '0.4%'),
    top: ({ oldHud }: UseStylesProps) => (oldHud ? '18.4703%' : '15%'),
    position: 'absolute',
    display: 'flex',
    flexWrap: 'wrap',
  },
  playerContainer: {
    width: ({ oldHud }: UseStylesProps) => (oldHud ? '46.41%' : '30%'),
    height: ({ oldHud }: UseStylesProps) => (oldHud ? '100%' : '109%'),
    borderRadius: ({ height }: UseStylesProps) => height / 100,
    transition: 'opacity .1s linear',
    marginBottom: ({ oldHud }: UseStylesProps) => (oldHud ? '2%' : '1.9%'),
    marginRight: ({ oldHud }: UseStylesProps) => (oldHud ? '2.34%' : '0.23%'),
    marginLeft: ({ oldHud }: UseStylesProps) => (oldHud ? '0%' : '2.4%'),
    boxSizing: 'border-box',
  },
}));

function useWindowSize() {
  const [windowSize, setWindowSize] = useState<[number, number]>([0, 0]);

  useEffect(() => {
    const onResize = () => {
      setWindowSize([window.innerWidth, window.innerHeight]);
    };
    window.addEventListener("resize", onResize);
    onResize();

    return () => window.removeEventListener("resize", onResize);
  }, []);
  return windowSize;
}

const query = new URLSearchParams(window.location.search.substring(1));
let loaded = false;
const App: React.FC = function () {
  const [voiceState, setVoiceState] = useState<VoiceState>({
    overlayState: {
      gameState: 0,
      players: [],
    },
    otherTalking: {},
    otherDead: {},
    localTalking: false,
    localIsAlive: false,
    mod: "NONE"
  });

  const [settings, setSettings] = useState<ISettings>({
    compactOverlay: false,
    overlayPosition: "right",
    meetingOverlay: true,
    serverURL: "",
    version: "DEV",
    secretString: undefined
  });
  const [cosmeticImages, setCosmeticImages] = useState<Record<string, string>>({});

  //   const socketRef = useRef<Socket | undefined>(undefined);
  useEffect(() => {
    let server = query.get("server");
    if (query.get("server")?.includes("://crewl.ink")) {
      server = "https://proxy.bettercrewl.ink";
    }
    const settings = {
      compactOverlay: query.get("compact") === "1",
      overlayPosition: query.get("position") || "right",
      meetingOverlay: query.get("meeting") === "1",
      serverURL: server || "https://bettercrewl.ink",
      version: query.get("version") || "DEV",
      secretString: query.get("secret") || undefined,
      mod: query.get("mod") ?? ""
    };
    setSettings(settings);
    if (!settings.secretString || settings.secretString?.length !== 9) {
      loaded = true;
      return;
    }
    console.log("GOT SETTINGS: ", settings, settings.secretString.length);

    console.log("called useffect..");
    let socket: CompatibleSocket | undefined;
    let fallbackTimer: number | undefined;
    let disposed = false;
    let fallbackStarted = false;
    let assetSession = '';
    let activeSources = new Set<string>();
    const receivedSources = new Set<string>();
    const requestedAt = new Map<string, number>();
    let senderSocketId = '';
    const requestMissing = () => {
      if (!socket?.connected || !senderSocketId || !assetSession) return;
      const now = Date.now();
      const sources = Array.from(activeSources).filter((source) => {
        if (!/^((nos-cosmetic:\/\/image\/)|(snr-cosmetic:\/\/skin\/))/.test(source) || source.length > 512) return false;
        if (receivedSources.has(source)) return false;
        if (now - (requestedAt.get(source) || 0) < 1500) return false;
        requestedAt.set(source, now);
        return true;
      }).slice(0, 4);
      if (sources.length) socket.emit('signal', {
        to: senderSocketId,
        data: { type: 'obs-cosmetics-request', secret: settings.secretString, sources },
      });
    };
    const retryTimer = window.setInterval(requestMissing, 1000);

    const joinRoom = (connectedSocket: CompatibleSocket) => {
      connectedSocket.emit(
        "join",
        settings.secretString,
        Math.floor(Math.random() * 20 + 0),
        Math.floor(Math.random() * 396 + 59000)
      );
    };

    const bindSocketEvents = (
      connectedSocket: CompatibleSocket,
      socketIoVersion: "4" | "2.4.0"
    ) => {
      socket = connectedSocket;
      connectedSocket.on("connect", () => {
        console.log(`[socketIO v${socketIoVersion}] connect`);
        if (fallbackTimer) {
          window.clearTimeout(fallbackTimer);
          fallbackTimer = undefined;
        }
        joinRoom(connectedSocket);
      });
      connectedSocket.on("disconnect", () => {
        console.log(`[socketIO v${socketIoVersion}] disconnect`);
      });
      connectedSocket.on("signal", (data: signalData) => {
        const payload = data?.data;
        if (!payload || typeof payload !== 'object') return;
        if ('type' in payload) {
          if (payload.type !== 'obs-cosmetic' || !activeSources.has(payload.source) ||
              typeof payload.png !== 'string' || !/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(payload.png) ||
              payload.png.length > 750000) return;
          receivedSources.add(payload.source);
          setCosmeticImages((old) => old[payload.source] === payload.png ? old : { ...old, [payload.source]: payload.png });
          return;
        }
        if (!payload.overlayState?.players) return;
        if (payload.assetSession !== assetSession) {
          assetSession = payload.assetSession || '';
          requestedAt.clear();
          receivedSources.clear();
          setCosmeticImages({});
        }
        activeSources = new Set(payload.overlayState.players.flatMap((player) =>
          [player.skinSource, player.bodyMaskSource].filter((source): source is string => !!source)
        ));
        senderSocketId = data.from || '';
        setVoiceState(payload);
        requestMissing();
      });
    };

    const connectWithSocketIo2 = (reason: string) => {
      if (disposed || fallbackStarted) return;
      fallbackStarted = true;
      if (fallbackTimer) {
        window.clearTimeout(fallbackTimer);
        fallbackTimer = undefined;
      }
      console.warn(`[socketIO] v4 connection failed (${reason}); falling back to v2.4.0`);
      socket?.disconnect();
      bindSocketEvents(
        ioV2(settings.serverURL, {
          transports: ["websocket"],
        }) as CompatibleSocket,
        "2.4.0"
      );
    };

    const socketV4 = ioV4(settings.serverURL, {
      transports: ["websocket"],
      timeout: 2500,
      reconnectionAttempts: 1,
    }) as CompatibleSocket;

    bindSocketEvents(socketV4, "4");
    socketV4.on("connect_error", (error: Error) => {
      connectWithSocketIo2(error.message);
    });
    fallbackTimer = window.setTimeout(() => {
      if (!socketV4.connected) connectWithSocketIo2("timeout");
    }, 3500);

    loaded = true;

    return () => {
      disposed = true;
      if (fallbackTimer) window.clearTimeout(fallbackTimer);
      window.clearInterval(retryTimer);
      socket?.disconnect();
    };
  }, []);


  // console.log("update??", voiceState, loaded);
  if ((!settings.secretString || settings.secretString.length !== 9) && loaded) {
    return (
      <>
        <h2 style={{ color: "black" }}>
          Hey, it seems that u didn't use the url from Bettercrewlink
          </h2>
      </>
    );
  }

  if (
    !loaded ||
    !settings ||
    !settings.secretString ||
    !voiceState ||
    !voiceState.overlayState ||
    voiceState.overlayState.gameState === GameState.MENU
  ) {
    // console.log(
    //   "error",
    //   settings,
    //   voiceState,
    //   voiceState.overlayState,
    //   voiceState.overlayState.gameState,
    //   voiceState.overlayState.gameState === GameState.MENU
    // );
    return null;
  }
  return (
    <>
      <OverlayWatermark
        serverURL={settings.serverURL}
        version={settings.version}
        lowered={voiceState.mod === "SUPER_NEW_ROLES"}
        inGame={voiceState.overlayState.gameState === GameState.TASKS}
        mod={voiceState.mod}
      />
      {settings.meetingOverlay &&
        voiceState.overlayState.gameState === GameState.DISCUSSION && (
          <MeetingHud
            gameState={voiceState.overlayState}
            voiceState={voiceState}
          />
        )}
      {settings.overlayPosition !== "hidden" && (
        <AvatarOverlay
          cosmeticImages={cosmeticImages}
          mod={voiceState.mod}
          voiceState={voiceState}
          gameState={voiceState.overlayState}
          position={settings.overlayPosition}
          compactOverlay={settings.compactOverlay}
        />
      )}
    </>
  );
};

interface OverlayWatermarkProps {
  serverURL: string;
  version: string;
  lowered: boolean;
  inGame: boolean;
  mod: ModsType;
}

const OverlayWatermark: React.FC<OverlayWatermarkProps> = ({
  serverURL,
  version,
  lowered,
  inGame,
  mod,
}: OverlayWatermarkProps) => {
  const isNoS = mod === "NoS";

  return (
    <div
      className={`tanuki-overlay-watermark${lowered ? " tanuki-overlay-watermark_snr" : ""}${
        inGame ? " tanuki-overlay-watermark_game" : ""
      }${isNoS ? " tanuki-overlay-watermark_nos" : ""}`}
    >
      <div>TanukiBCL v{version}</div>
      <div>{serverURL}</div>
    </div>
  );
};

interface AvatarOverlayProps {
  cosmeticImages: Record<string, string>;
  voiceState: VoiceState;
  gameState: OverlayState;
  position: ISettings["overlayPosition"];
  compactOverlay: boolean;
  mod: ModsType;
}

const AvatarOverlay: React.FC<AvatarOverlayProps> = ({
  cosmeticImages,
  voiceState,
  gameState,
  position,
  compactOverlay,
  mod,
}: AvatarOverlayProps) => {
  const avatars: JSX.Element[] = [];
  const positionParse = position.replace("1", "");
  const isOnSide = positionParse === "right" || positionParse === "left";
  const showName =
    isOnSide &&
    (!compactOverlay || position === "right1" || position === "left1");
  const classnames: string[] = ["overlay-wrapper"];

  if (
    gameState.gameState === GameState.UNKNOWN ||
    gameState.gameState === GameState.MENU
  ) {
    classnames.push("gamestate_menu");
  } else {
    classnames.push("gamestate_game");
    classnames.push("overlay_postion_" + positionParse);
    if (compactOverlay || position === "right1" || position === "left1") {
      classnames.push("compactoverlay");
    }
    if (position === "left1" || position === "right1") {
      classnames.push("overlay_postion_" + position);
    }
  }
  const players = useMemo(() => {
    // console.log("updating players");
    if (!gameState.players) return null;
    const playerss = gameState.players
      .filter(
        (o) => !voiceState.localIsAlive || !voiceState.otherDead[o.clientId]
      )
      .slice()
      .sort((a, b) => {
        if (
          (a.disconnected || voiceState.otherDead[a.clientId]) &&
          (b.disconnected || voiceState.otherDead[a.clientId])
        ) {
          return a.id - b.id;
        } else if (a.disconnected || voiceState.otherDead[a.clientId]) {
          return 1000;
        } else if (b.disconnected || voiceState.otherDead[b.clientId]) {
          return -1000;
        }
        return a.id - b.id;
      });
    return playerss;
  }, [gameState.players, voiceState.localIsAlive, voiceState.otherDead]);
  // console.log(gameState.players);
  players?.forEach((player) => {
    if (
      !voiceState.otherTalking[player.clientId] &&
      !(player.isLocal && voiceState.localTalking) &&
      compactOverlay
    )
      return;
    // const peer = voiceState.playerSocketIds[player.clientId];

    if (!player.connected && !player.isLocal) return;
    const talking =
      !player.inVent &&
      (voiceState.otherTalking[player.clientId] ||
        (player.isLocal && voiceState.localTalking));

    // const audio = voiceState.audioConnected[peer];
    avatars.push(
      <div key={player.id} className="player_wrapper">
        <div>
          <Avatar
            customSkin={player.skinSource ? cosmeticImages[player.skinSource] : undefined}
            bodyMask={player.bodyMaskSource ? cosmeticImages[player.bodyMaskSource] : undefined}
            key={player.id}
            // connectionState={!connected ? 'disconnected' : audio ? 'connected' : 'novoice'}
            player={player}
            showborder={isOnSide && !compactOverlay}
           // muted={player.isLocal}
           // deafened={player.isLocal}
            connectionState={'connected'}
            talking={talking}
            borderColor="#2ecc71"
            isAlive={!voiceState.otherDead[player.clientId] || (player.isLocal && !player.isDead)}
            size={100}
            lookLeft={!(positionParse === 'left' || positionParse === 'bottom_left')}
            overflow={isOnSide && !showName}
            showHat={true}
            mod={voiceState.mod}
          />
        </div>
        {showName && (
          <span
            className="playername"
            style={{
              opacity: (position === 'right1' || position === 'left1') && !talking ? 0 : 1,
            }}
          >
            <small>{player.name}</small>
          </span>
        )}
      </div>
    );
  });
  if (avatars.length === 0) return null;
  return (
    <div>
      <div className={classnames.join(" ")} style={{ '--size' :  7.5 * (10 / avatars.length) + "vh" } as playerContainerCss}>
        <div className="otherplayers">
          <div className="players_container playerContainerBack">{avatars}</div> 
        </div>
      </div>
    </div>
  );
};

interface MeetingHudProps {
  gameState: OverlayState;
  voiceState: VoiceState;
}

const MeetingHud: React.FC<MeetingHudProps> = ({
  voiceState,
  gameState,
}: MeetingHudProps) => {
  const [windowWidth, windowheight] = useWindowSize();
	const [width, height] = useMemo(() => {
		let resultW;
		let ratio_diff = Math.abs(windowWidth / windowheight - 1.7);

		if (ratio_diff < 0.25) {
			resultW = windowWidth / 1.192
		} else if (ratio_diff < 0.5) {
			resultW = windowWidth / 1.146
		} else {
			resultW = windowWidth / 1.591;
		}

		let resultH = resultW / 1.72;
		// console.log("Ratio: ", windowWidth, windowheight, ratio.toFixed(1), ratio, Math.round(ratio * 10) / 10, Math.abs(ratio - 1.7))
		return [resultW, resultH];
	}, [windowWidth, windowheight]);

	const classes = useStyles({
		width: width,
		height: height,
		oldHud: false
	});
  
  const players = useMemo(() => {
    if (!gameState.players) return null;
    return gameState.players.slice().sort((a, b) => {
      if ((a.disconnected || a.isDead) && (b.disconnected || b.isDead)) {
        return a.id - b.id;
      } else if (a.disconnected || a.isDead) {
        return 1000;
      } else if (b.disconnected || b.isDead) {
        return -1000;
      }
      return a.id - b.id;
    });
  }, [gameState.players]);

  if (!players || gameState.gameState !== GameState.DISCUSSION) return null;
  const overlays = players.map((player) => {
   

    const avatarColors = getAvatarColors(player.realColor, player.nosColor);
    const color = (!avatarColors || avatarColors.length === 0)? "#0000" : avatarColors[0];

    return (
      <div
        key={player.id}
        className={classes.playerContainer}
        style={{
          opacity: voiceState.otherTalking[player.clientId] || (player.isLocal && voiceState.localTalking) ? 1 : 0,
          border: 'solid',
          borderWidth: '2px',
          borderColor: '#00000037',
          boxShadow: `0 0 ${height / 100}px ${height / 100}px ${color}`,
          transition: 'opacity 400ms',
        }}
      />
    );
  });

  return (
    <div className={classes.meetingHud}>
      <div className={classes.tabletContainer}>{overlays}</div>
    </div>
  ); 

};

export default App;
