import React, { useEffect, useState } from 'react';
import { ModsType, overlayPlayer } from './common/AmongUsState';
import {
	getCosmetic,
	redAlive,
	cosmeticType,
	getHatDementions,
	initializeHats,
	HatDementions,
} from "./common/cosmetics";
import makeStyles from '@material-ui/core/styles/makeStyles';
import MicOff from '@material-ui/icons/MicOff';
import VolumeOff from '@material-ui/icons/VolumeOff';
import WifiOff from '@material-ui/icons/WifiOff';
import LinkOff from '@material-ui/icons/LinkOff';
import ErrorOutline from '@material-ui/icons/ErrorOutline'; //@ts-ignore
import RadioSVG from './static/radio.svg';
import { getAvatarColors } from './common/AvatarGenerator';


const useStyles = makeStyles(() => ({
	canvas: {
		position: 'absolute',
		width: '100%',
	},
	icon: {
		background: '#ea3c2a',
		position: 'absolute',
		left: '50%',
		top: '50%',
		transform: 'translate(-50%, -50%)',
		border: '2px solid #690a00',
		borderRadius: '50%',
		padding: 2,
		zIndex: 10,
	},
	iconNoBackground: {
		position: 'absolute',
		left: '50%',
		top: '50%',
		transform: 'translate(-50%, -50%)',
		borderRadius: '50%',
		padding: 2,
		zIndex: 10,
	},
	relative: {
		position: 'relative',
	},
	slidecontainer: {
		minWidth: '80px',
	},
	innerTooltip: {
		textAlign: 'center',
	},
}));

export interface CanvasProps {
	customSkin?: string;
	bodyMask?: string;
	hat: string;
	skin: string;
	visor: string;
	isAlive: boolean;
	className: string;
	lookLeft: boolean;
	size: number;
	borderColor: string;
	talking: boolean;
	showborder?: boolean;
	realColor: string[];
	color: number;
	overflow: boolean;
	usingRadio: boolean | undefined;
	onClick?: () => void;
	mod: ModsType;
}

export interface AvatarProps {
	customSkin?: string;
	bodyMask?: string;
	talking: boolean;
	borderColor: string;
	isAlive: boolean;
	player: overlayPlayer;
	size: number;
	deafened?: boolean;
	muted?: boolean;
	connectionState?: 'disconnected' | 'novoice' | 'connected';
	showborder?: boolean;
	showHat?: boolean;
	lookLeft?: boolean;
	overflow?: boolean;
	isUsingRadio?: boolean;
	onConfigChange?: () => void;
	mod: ModsType;
}

const Avatar: React.FC<AvatarProps> = function ({
	customSkin,
	bodyMask,
	talking,
	deafened,
	muted,
	borderColor,
	isAlive,
	player,
	size,
	connectionState,
	showborder,
	showHat,
	isUsingRadio,
	lookLeft = false,
	overflow = false,
	onConfigChange,
	mod,
}: AvatarProps) {
	const classes = useStyles();
	let icon;
	deafened = deafened === true;
	switch (connectionState) {
		case 'connected':
			if (deafened) {
				icon = <VolumeOff className={classes.icon} />;
			} else if (muted) {
				icon = <MicOff className={classes.icon} />;
			}
			break;
		case 'novoice':
			icon = <LinkOff className={classes.icon} style={{ background: '#e67e22', borderColor: '#694900' }} />;
			break;
		case 'disconnected':
			icon = <WifiOff className={classes.icon} />;
			break;
	}
	if (player.bugged) {
		icon = <ErrorOutline className={classes.icon} style={{ background: 'red', borderColor: '' }} />;
	}


	const canvas = (
		<Canvas
			customSkin={customSkin}
			bodyMask={bodyMask}
			className={classes.canvas}
			color={player.colorId}
			hat={showHat === false ? '' : player.hatId}
			visor={showHat === false ? '' : player.visorId}
			skin={player.skinId}
			isAlive={isAlive}
			realColor={getAvatarColors(player.realColor, player.nosColor)}
			lookLeft={lookLeft === true}
			borderColor={borderColor}
			talking={talking}
			showborder={showborder}
			size={size}
			overflow={overflow}
			usingRadio={isUsingRadio}
			mod={mod}
		/>
	);
	return (
		<div className={classes.relative}>
			{canvas}
			{icon}
		</div>
	);
};

interface UseCanvasStylesParams {
	isAlive: boolean;
	dementions: {
		hat: HatDementions;
		visor: HatDementions;
		skin: HatDementions;
	};
	lookLeft: boolean;
	size: number;
	paddingLeft: number;
}
const useCanvasStyles = makeStyles(() => ({
	base: {
		width: '105%',
		position: 'absolute',
		top: '22%',
		left: ({ paddingLeft }: UseCanvasStylesParams) => paddingLeft,
		zIndex: 2,
	},
	hat: {
		pointerEvents: 'none',
		width: ({ dementions }: UseCanvasStylesParams) => dementions.hat.width,
		position: 'absolute',
		top: ({ dementions }: UseCanvasStylesParams) => `calc(22% + ${dementions.hat.top})`,
		left: ({ size, paddingLeft, dementions }: UseCanvasStylesParams) =>
			`calc(${dementions.hat.left} + ${Math.max(2, size / 40) / 2 + paddingLeft}px)`,
		zIndex: 4,
		display: ({ isAlive }: UseCanvasStylesParams) => (isAlive ? 'block' : 'none'),
	},
	skin: {
		pointerEvents: 'none',
		width: ({ dementions }: UseCanvasStylesParams) => dementions.skin.width,
		position: 'absolute',
		top: ({ dementions }: UseCanvasStylesParams) => `calc(22% + ${dementions.skin.top})`,
		left: ({ size, paddingLeft, dementions }: UseCanvasStylesParams) =>
			`calc(${dementions.skin.left} + ${Math.max(2, size / 40) / 2 + paddingLeft}px)`,
		zIndex: 3,
		display: ({ isAlive }: UseCanvasStylesParams) => (isAlive ? 'block' : 'none'),
	},
	visor: {
		pointerEvents: 'none',
		width: ({ dementions }: UseCanvasStylesParams) => dementions.visor.width,
		position: 'absolute',
		top: ({ dementions }: UseCanvasStylesParams) => `calc(22% + ${dementions.visor.top})`,
		left: ({ size, paddingLeft, dementions }: UseCanvasStylesParams) =>
			`calc(${dementions.visor.left} + ${Math.max(2, size / 40) / 2 + paddingLeft}px)`,
		zIndex: 3,
		display: ({ isAlive }: UseCanvasStylesParams) => (isAlive ? 'block' : 'none'),
	},
	avatar: {
		// overflow: 'hidden',
		borderRadius: '50%',
		position: 'relative',
		borderStyle: 'solid',
		transition: 'border-color .2s ease-out',
		borderColor: 'transparent',
		borderWidth: ({ size }: UseCanvasStylesParams) => Math.max(2, size / 40),
		transform: ({ lookLeft }: UseCanvasStylesParams) => (lookLeft ? 'scaleX(-1)' : 'scaleX(1)'),
		width: '100%',
		paddingBottom: '100%',
		cursor: 'pointer',
		'&.avatar-show-border': {
			borderColor: '#ccbdcc86',
		},
		'&.avatar-talking': {
			borderColor: 'var(--talking-border-color)',
		},
	},
	radio: {
		position: 'absolute',
		left: '70%',
		top: '80%',
		width: '30px',
		transform: 'translate(-50%, -50%)',
		fill: 'white',
		padding: 2,
		zIndex: 12,
	},
}));

function Canvas({
	customSkin,
	bodyMask,
	hat,
	skin,
	visor,
	isAlive,
	lookLeft,
	size,
	borderColor,
	talking,
	showborder,
	color,
	realColor,
	overflow,
	usingRadio,
	onClick,
	mod,
}: CanvasProps) {

	const [hatImg, setHatImg] = useState({
		base: '',
		hat_front: '',
		hat_back: '',
		skin: '',
		visor: '',
		dementions: {
			hat: {
				top: '0',
				width: '0',
				left: '0',
			},
			visor: {
				top: '0',
				width: '0',
				left: '0',
			},
			skin: {
				top: '0',
				width: '0',
				left: '0',
			},
		},
	})

	const primaryColor = realColor[0];
	const secondaryColor = realColor[1];
	useEffect(() => {
		let disposed = false;
		const loadHatImages = async () => {
			const colors = [primaryColor, secondaryColor];
			const basePromise = getCosmetic(colors, isAlive, cosmeticType.base);
			const hatsReady = initializeHats().catch((error) => {
				console.error('Unable to load overlay cosmetics', error);
			});
			const base = await basePromise;
			if (!disposed) setHatImg((previous) => ({ ...previous, base }));
			await hatsReady;
			const [hat_front, hat_back, skinImage, visorImage] = await Promise.all([
				getCosmetic(colors, isAlive, cosmeticType.hat, hat, mod),
				getCosmetic(colors, isAlive, cosmeticType.hat_back, hat, mod),
				customSkin ? Promise.resolve(customSkin) : getCosmetic(colors, isAlive, cosmeticType.hat, skin, mod),
				getCosmetic(colors, isAlive, cosmeticType.hat, visor, mod),
			]);
			const nextHatImg = {
				base,
				hat_front,
				hat_back,
				skin: skinImage,
				visor: visorImage,
				dementions: {
					hat: getHatDementions(hat, mod),
					visor: getHatDementions(visor, mod),
				skin: customSkin
					? { top: '-52%', width: '140%', left: '-18px' }
					: getHatDementions(skin, mod),
				},
			};
			if (!disposed) setHatImg(nextHatImg);
		};
		loadHatImages();
		return () => {
			disposed = true;
		};
	}, [color, hat, skin, visor, isAlive, primaryColor, secondaryColor, mod, customSkin]);

	const classes = useCanvasStyles({
		isAlive,
		dementions: customSkin ? {
			...hatImg.dementions,
			skin: { top: '-52%', width: '140%', left: '-18px' },
		} : hatImg.dementions,
		lookLeft,
		size,
		paddingLeft: -7,
	});
	//@ts-ignore
	const onerror = (e: any) => {
		e.target.style.display = 'none';
	};

	//@ts-ignore
	const onload = (e: any) => {
		e.target.style.display = '';
	};

	const hatElement = (
		<>
			<img src={hatImg.hat_front} className={classes.hat} onError={onerror} onLoad={onload} alt="" />
			<img src={hatImg.visor} className={classes.visor} onError={onerror} onLoad={onload} alt="" />

			<img src={hatImg.hat_back} className={classes.hat} style={{ zIndex: 1 }} onError={onerror} onLoad={onload} alt="" />
		</>
	);
	const avatarClassName = [
		classes.avatar,
		showborder === true ? 'avatar-show-border' : '',
		talking ? 'avatar-talking' : '',
	]
		.filter(Boolean)
		.join(' ');
	const avatarStyle = { '--talking-border-color': borderColor } as React.CSSProperties;
	const bodyMaskStyle = bodyMask ? {
		WebkitMaskImage: `url(${bodyMask})`,
		maskImage: `url(${bodyMask})`,
		WebkitMaskSize: '140% auto',
		maskSize: '140% auto',
		WebkitMaskPosition: `${-25 + Math.max(2, size / 40) / 2}px ${size * -0.3}px`,
		maskPosition: `${-25 + Math.max(2, size / 40) / 2}px ${size * -0.3}px`,
		WebkitMaskRepeat: 'no-repeat' as const,
		maskRepeat: 'no-repeat' as const,
	} : undefined;

	return (
		<>
			<div className={avatarClassName} style={avatarStyle} onClick={onClick}>
				<div
					className={avatarClassName}
					style={{
						...avatarStyle,
						overflow: 'hidden',
						position: 'absolute',
						top: Math.max(2, size / 40) * -1,
						left: Math.max(2, size / 40) * -1,
						transform: 'unset',
					}}
				>
					<div style={{ position: 'absolute', inset: 0, zIndex: 2, ...bodyMaskStyle }}>
					<img
						src={hatImg.base}
						className={classes.base}
						//@ts-ignore
						onError={(e: any) => {
							e.target.onError = null;
							e.target.src = redAlive;
						}}
						alt=""
					/>
					</div>

					<img src={customSkin || hatImg.skin} className={classes.skin} onError={onerror} onLoad={onload} alt="" />
					{overflow && hatElement}
				</div>
				{!overflow && hatElement}
				{usingRadio && <img src={RadioSVG} className={classes.radio} alt="" />}
			</div>
		</>
	);
}

export default Avatar;
